INSERT INTO "default_asset_types" ("name", "description") VALUES
  ('Mechanical Equipment', 'Mechanical machinery used for industrial operations and maintenance. Examples: pumps, compressors, motors, fans, blowers, gearboxes, turbines.'),
  ('Electrical Equipment', 'Equipment used for electrical power generation, distribution, switching, and control. Examples: transformers, switchgear, generators, electrical panels, motor control centers, UPS systems.'),
  ('Piping & Valves', 'Piping systems and components used to transport fluids, gases, steam, or other process media. Examples: pipelines, process pipes, valves, manifolds, flanges, pipe spools.'),
  ('Vessels & Tanks', 'Equipment designed to contain, store, or process liquids, gases, or other materials. Examples: pressure vessels, storage tanks, reactors, boilers, silos, drums.'),
  ('HVAC & Ventilation', 'Equipment used for heating, ventilation, air conditioning, and temperature control. Examples: chillers, air handling units, exhaust fans, ventilation systems, cooling coils.'),
  ('Instrumentation & Control', 'Devices and systems used to measure, monitor, automate, and control industrial processes. Examples: sensors, transmitters, analyzers, PLCs, DCS panels, control valves.'),
  ('Production Machinery', 'Machines used for manufacturing, processing, assembly, or packaging operations. Examples: CNC machines, presses, packaging machines, filling machines, assembly lines.'),
  ('Material Handling Equipment', 'Equipment used to move, lift, transport, or position materials and goods. Examples: conveyors, cranes, hoists, forklifts, winches, pallet handling systems.'),
  ('Utilities Equipment', 'Equipment supporting essential utility services required for facility operations. Examples: air compressors, water treatment units, cooling towers, steam systems, industrial water pumps.'),
  ('Fire & Safety Systems', 'Equipment and systems designed to detect, prevent, or control fires and protect personnel. Examples: fire pumps, sprinkler systems, fire alarm panels, smoke detectors, fire suppression systems.'),
  ('Civil & Structural Assets', 'Buildings, structures, and civil infrastructure requiring inspection, repair, or maintenance. Examples: buildings, foundations, platforms, bridges, structural steel, roofs, walkways.'),
  ('IT & Data Center Equipment', 'Information technology and supporting infrastructure equipment used in IT facilities and data centers. Examples: server racks, network cabinets, power distribution units, fiber distribution frames, data center cooling units.'),
  ('Vehicles & Mobile Equipment', 'Mobile machinery and vehicles used for transportation, construction, lifting, or industrial operations. Examples: trucks, excavators, mobile cranes, loaders, trailers, aerial work platforms.'),
  ('Marine Equipment', 'Equipment used in ships, shipyards, offshore facilities, and marine operations. Examples: marine engines, winches, mooring equipment, cargo handling systems, gangways, davits.'),
  ('Railway & Transport Equipment', 'Equipment and infrastructure components used in railway and transport operations. Examples: railway switches, signaling equipment, track machinery, rail maintenance vehicles, platform equipment.'),
  ('Aviation & Airport Equipment', 'Equipment used for aircraft servicing, airport operations, and ground handling. Examples: ground support equipment, baggage handling systems, aircraft towing tractors, boarding bridges.'),
  ('Mining Equipment', 'Machinery and equipment used in mining, mineral extraction, and ore processing operations. Examples: crushers, drilling rigs, excavators, haul trucks, screening machines, conveyors.'),
  ('Laboratory & Pharmaceutical Equipment', 'Equipment used in laboratory testing, pharmaceutical manufacturing, and life sciences operations. Examples: laboratory instruments, autoclaves, bioreactors, centrifuges, mixing vessels, cleanroom equipment.'),
  ('General Equipment', 'General-purpose equipment used for maintenance, workshop activities, and facility operations that does not fit another category. Examples: workbenches, workshop machinery, maintenance equipment, portable equipment.'),
  ('Other', 'Assets that do not fit any of the predefined asset type categories. Examples: specialized equipment or unique assets specific to a tenant or facility.');
--> statement-breakpoint
INSERT INTO "default_hazards" ("code", "name", "category", "severity", "description", "risks", "consequences", "controls", "permit_type_codes") VALUES
  ('HAZ-FIRE-001', 'Fire and Ignition', 'Fire and Explosion', 'critical', 'Ignition of combustible or flammable materials due to flames, sparks, hot surfaces, or other ignition sources.', '["Ignition of flammable vapours","Sparks reaching combustible materials","Inadequate separation of hot work from hazardous substances."]'::jsonb, '["Burns","fire spread","fatalities","equipment damage","production loss"]'::jsonb, '["Remove or protect combustible materials","Verify flammable atmospheres are controlled where relevant","Inspect the work area before starting","Provide suitable firefighting equipment and a trained fire watch where required","Monitor the area during work and for the site-defined period afterward"]'::jsonb, ARRAY['HOT','COLD','CSP','WAH','ELEC']::varchar[]),
  ('HAZ-FIRE-002', 'Explosion / Flammable Atmosphere', 'Fire and Explosion', 'critical', 'Presence or possible accumulation of flammable gases, vapours, mists, or combustible dust that can ignite or explode.', '["Ignition by sparks, static discharge, electrical equipment, or hot work","Accumulation of flammable substances","Uncontrolled release of flammable materials."]'::jsonb, '["Blast injuries","burns","structural damage","multiple fatalities"]'::jsonb, '["Identify flammable substances and potential release sources","Isolate and eliminate leaks where practicable","Conduct atmospheric testing using suitable calibrated equipment where required","Maintain ventilation and monitor conditions as specified by the risk assessment","Control ignition sources and use appropriately rated equipment in classified areas"]'::jsonb, ARRAY['HOT','COLD','CSP','ELEC']::varchar[]),
  ('HAZ-THERM-001', 'Hot Surfaces and Thermal Burns', 'Thermal', 'high', 'Exposure to heated equipment, molten material, hot workpieces, steam, or other high-temperature surfaces.', '["Accidental contact with hot surfaces","Hot material splashes","Unexpected release of steam or heat."]'::jsonb, '["Skin burns","eye injuries","serious tissue damage"]'::jsonb, '["Allow equipment to cool where possible","Isolate heat and pressure sources before work","Install barriers and warning signs","Use task-appropriate thermal PPE","Verify temperature before handling equipment or materials"]'::jsonb, ARRAY['HOT','COLD','CSP','ELEC']::varchar[]),
  ('HAZ-AIR-001', 'Smoke, Welding Fumes and Harmful Dust', 'Chemical / Airborne Exposure', 'high', 'Generation or accumulation of welding fumes, grinding dust, airborne particulates, or harmful vapours during work.', '["Inhalation of toxic substances","Exposure to metal fumes","Inadequate ventilation","Secondary exposure to nearby workers."]'::jsonb, '["Respiratory irritation","occupational illness","lung damage","acute poisoning"]'::jsonb, '["Assess the materials and expected contaminants","Use local exhaust ventilation or suitable extraction","Provide suitable respiratory protection where required","Prevent exposure to nearby personnel","Apply atmospheric monitoring where the substances and task warrant it"]'::jsonb, ARRAY['HOT','COLD','CSP','ELEC']::varchar[]),
  ('HAZ-ELEC-001', 'Electric Shock and Electrocution', 'Electrical', 'critical', 'Exposure to live electrical conductors, faulty equipment, damaged insulation, or unexpected energization.', '["Direct or indirect electrical contact","Current passing through the body","Contact with energized metalwork."]'::jsonb, '["Electric shock","electrical burns","cardiac arrest","electrocution"]'::jsonb, '["Isolate all relevant electrical supplies where required","Apply lockout/tagout and verify absence of voltage using suitable equipment","Restrict work to competent, authorized personnel","Inspect tools, cables, and protective devices","Apply approved energized-work procedures only where justified and permitted"]'::jsonb, ARRAY['HOT','COLD','CSP','WAH','ELEC']::varchar[]),
  ('HAZ-ELEC-002', 'Arc Flash and Arc Blast', 'Electrical', 'critical', 'Release of intense thermal energy, pressure, and debris from an electrical arc fault.', '["Switching or testing faults","Short circuits","Accidental contact","Electrical equipment failure."]'::jsonb, '["Severe burns","blast injuries","hearing damage","permanent disability","fatalities"]'::jsonb, '["Assess arc-flash risk and incident energy where applicable","De-energize equipment where practicable","Establish approach boundaries and restrict access","Use appropriately rated PPE and tools","Follow approved switching and electrical-work procedures"]'::jsonb, ARRAY['HOT','COLD','ELEC']::varchar[]),
  ('HAZ-ENERGY-001', 'Unexpected Energization / Stored Energy', 'Hazardous Energy', 'critical', 'Unexpected startup, movement, release, or energization of equipment or systems during maintenance.', '["Residual electrical charge","Rotating machinery","Springs","Hydraulic accumulators","Pneumatic pressure","Gravity","Remote startup."]'::jsonb, '["Crushing","entanglement","amputation","electrocution","fatalities"]'::jsonb, '["Identify all energy sources and isolation points","Apply approved isolation and lockout/tagout procedures","Release or restrain stored energy","Verify the safe, zero-energy state before work","Control the removal of locks and restoration of energy"]'::jsonb, ARRAY['HOT','COLD','CSP','WAH','ELEC','EXC']::varchar[]),
  ('HAZ-MECH-001', 'Mechanical Movement / Rotating Machinery', 'Mechanical', 'high', 'Exposure to moving machinery, rotating components, pinch points, or mechanical forces.', '["Entanglement","Trapping","Crushing","Contact with moving parts","Unexpected movement."]'::jsonb, '["Lacerations","fractures","amputations","permanent disability","fatalities"]'::jsonb, '["Isolate and secure machinery before intervention","Verify that moving parts have stopped","Guard exposed moving components","Use suitable tools and safe work methods","Prevent unauthorized startup"]'::jsonb, ARRAY['HOT','COLD','CSP','ELEC']::varchar[]),
  ('HAZ-ATM-001', 'Oxygen Deficiency', 'Atmospheric', 'critical', 'An atmosphere with insufficient oxygen to safely support human life, potentially caused by displacement, consumption, or inerting.', '["Entry into an oxygen-deficient space","Oxygen displacement by inert gases","Oxygen depletion from chemical or biological processes."]'::jsonb, '["Dizziness","unconsciousness","asphyxiation","fatalities"]'::jsonb, '["Test the atmosphere before entry and as frequently as required","Isolate inert-gas and other supply sources","Provide suitable ventilation","Use continuous monitoring where required by the assessment","Establish rescue arrangements that do not rely on unprotected entry"]'::jsonb, ARRAY['HOT','COLD','CSP','ELEC']::varchar[]),
  ('HAZ-ATM-002', 'Toxic Gas / Harmful Atmosphere', 'Atmospheric / Chemical', 'critical', 'Presence or potential release of toxic gases, vapours, or airborne contaminants.', '["Exposure to toxic process gases","Exposure to cleaning chemicals","Exposure to decomposition products or harmful vapours."]'::jsonb, '["Poisoning","respiratory failure","permanent injury","fatalities"]'::jsonb, '["Identify substances and their exposure limits","Isolate release sources where possible","Test for relevant contaminants using appropriate equipment","Ventilate and monitor the atmosphere as required","Provide suitable respiratory protection and emergency rescue arrangements"]'::jsonb, ARRAY['HOT','COLD','CSP','ELEC']::varchar[]),
  ('HAZ-ATM-003', 'Flammable Atmosphere in Confined Space', 'Atmospheric / Fire and Explosion', 'critical', 'Accumulation of flammable gas, vapour, mist, or combustible dust in an enclosed or poorly ventilated area.', '["Ignition from hot work","Electrical faults","Static electricity","Use of unsuitable tools."]'::jsonb, '["Explosion","burns","structural damage","fatalities"]'::jsonb, '["Test the atmosphere before entry and hot work","Eliminate ignition sources and control hazardous releases","Apply required isolation, purging, and ventilation","Use appropriately rated equipment","Stop work and evacuate if conditions breach approved limits"]'::jsonb, ARRAY['HOT','COLD','CSP','ELEC']::varchar[]),
  ('HAZ-ENV-001', 'Heat Stress / Poor Ventilation', 'Environmental / Occupational Health', 'high', 'Exposure to high temperatures, humidity, radiant heat, or inadequate ventilation during work.', '["Heat accumulation","Strenuous activity","Restricted air movement","Dehydration."]'::jsonb, '["Heat exhaustion","heatstroke","impaired judgment","collapse","fatalities"]'::jsonb, '["Assess environmental and workload conditions","Provide ventilation, hydration, and suitable rest periods","Limit exposure and schedule work appropriately","Monitor workers for symptoms","Maintain communication and emergency arrangements"]'::jsonb, ARRAY['HOT','COLD','CSP','WAH']::varchar[]),
  ('HAZ-HEIGHT-001', 'Fall from Height', 'Work at Height', 'critical', 'Exposure to unprotected edges, openings, fragile surfaces, or elevated work positions.', '["Loss of balance","Ladder failure","Unsafe access","Failure of fall protection."]'::jsonb, '["Fractures","head injuries","permanent disability","fatalities"]'::jsonb, '["Prioritize safe platforms and collective protection","Inspect scaffolds and ladders","Protect openings and edges","Use suitable fall-arrest or restraint systems with appropriate anchorage","Establish a rescue plan"]'::jsonb, ARRAY['HOT','COLD','WAH','ELEC']::varchar[]),
  ('HAZ-HEIGHT-002', 'Falling Objects', 'Work at Height / Dropped Objects', 'high', 'Tools, materials, debris, or equipment falling from elevated work areas.', '["Dropped tools","Unsecured materials","Dislodged components","Simultaneous work above and below."]'::jsonb, '["Head injuries","fractures","crushing injuries","fatalities"]'::jsonb, '["Secure tools and materials","Use tool lanyards where suitable","Install toe boards or debris containment","Establish exclusion zones","Coordinate work at different elevations","Require appropriate head protection"]'::jsonb, ARRAY['HOT','COLD','WAH','ELEC']::varchar[]),
  ('HAZ-STRUCT-001', 'Structural Instability / Platform Failure', 'Structural / Access', 'critical', 'Failure or instability of scaffolds, temporary platforms, roofs, floors, supports, or structures.', '["Overloading","Inadequate foundations","Damaged components","Unstable surfaces","Unauthorized modifications."]'::jsonb, '["Falls","collapse","crush injuries","multiple fatalities"]'::jsonb, '["Verify load capacity and structural condition","Inspect and approve temporary structures","Prevent overloading","Protect fragile surfaces","Restrict access until the structure is confirmed safe"]'::jsonb, ARRAY['HOT','COLD','WAH','EXC']::varchar[]),
  ('HAZ-EXC-001', 'Excavation Collapse / Ground Failure', 'Excavation / Ground Stability', 'critical', 'Collapse of excavation walls, trenches, embankments, or unstable ground.', '["Unsupported excavation faces","Vibration","Water ingress","Nearby loads","Unsuitable soil conditions."]'::jsonb, '["Burial","crushing","suffocation","serious injury","fatalities"]'::jsonb, '["Assess ground conditions","Provide suitable shoring, shielding, or sloping","Inspect excavations","Control water ingress and nearby loads","Prevent entry into unsafe excavations","Provide safe access and egress"]'::jsonb, ARRAY['EXC']::varchar[]),
  ('HAZ-EXC-002', 'Underground Utilities / Buried Services', 'Excavation / Utilities', 'critical', 'Contact with or damage to buried electrical cables, gas lines, pipelines, drains, or communication services.', '["Excavating without verified service locations","Inaccurate drawings","Accidental penetration of buried infrastructure."]'::jsonb, '["Electrocution","fire","explosion","flooding","toxic releases","service disruption"]'::jsonb, '["Review utility drawings","Obtain required service-owner clearances","Locate and mark services using suitable detection methods","Use controlled digging methods near identified services","Isolate services where necessary","Stop work if unexpected services are discovered"]'::jsonb, ARRAY['HOT','COLD','ELEC','EXC']::varchar[]),
  ('HAZ-TRAFFIC-001', 'Mobile Plant / Vehicle Interaction', 'Vehicle / Equipment Movement', 'high', 'Exposure to moving vehicles, excavators, loaders, cranes, or other mobile equipment around the work area.', '["Blind spots","Reversing","Restricted visibility","Unstable ground","Pedestrian and vehicle route conflicts."]'::jsonb, '["Collision","crushing","run-over injuries","fatalities"]'::jsonb, '["Establish traffic and pedestrian segregation","Use competent operators and trained spotters where needed","Define exclusion zones","Verify ground bearing capacity","Control reversing","Use suitable barriers and warning systems"]'::jsonb, ARRAY['HOT','COLD','WAH','EXC']::varchar[]),
  ('HAZ-EXC-003', 'Water Ingress / Flooding / Engulfment', 'Excavation / Environmental', 'high', 'Water, slurry, loose material, or other substances entering an excavation or work area and creating entrapment or engulfment hazards.', '["Groundwater ingress","Damaged water services","Heavy rainfall","Unstable saturated soil","Nearby material release."]'::jsonb, '["Drowning","burial","collapse","hypothermia","fatalities"]'::jsonb, '["Assess water sources and weather","Provide suitable drainage or pumping","Monitor ground stability","Protect against material ingress","Maintain safe escape routes","Stop work and evacuate when conditions become unsafe"]'::jsonb, ARRAY['CSP','EXC']::varchar[]),
  ('HAZ-CHEM-001', 'Hazardous Chemical Exposure', 'Chemical', 'high', 'Contact with or exposure to corrosive, toxic, irritant, reactive, or otherwise hazardous substances.', '["Splashing","Spills","Inhalation","Skin absorption","Incompatible chemical reactions."]'::jsonb, '["Chemical burns","poisoning","eye damage","respiratory injury","environmental contamination"]'::jsonb, '["Review safety data sheets","Assess chemical compatibility","Use suitable containment and ventilation","Provide substance-specific PPE and eyewash or emergency showers where required","Maintain spill-response arrangements"]'::jsonb, ARRAY['HOT','COLD','CSP','ELEC','EXC']::varchar[]),
  ('HAZ-PRESS-001', 'Pressure Release / Stored Pressure', 'Pressure / Mechanical Energy', 'critical', 'Uncontrolled release of pressurized gas, liquid, steam, or other stored pressure during work.', '["Opening pressurized equipment","Failed hoses","Trapped pressure","Incorrect isolation","Pressure surges."]'::jsonb, '["Injection injuries","impact injuries","burns","toxic exposure","equipment damage","fatalities"]'::jsonb, '["Identify pressure sources","Isolate and depressurize equipment","Drain or vent safely","Verify zero pressure","Secure hoses and fittings","Use approved pressure limits and exclusion zones for testing"]'::jsonb, ARRAY['HOT','COLD','CSP','ELEC','EXC']::varchar[]),
  ('HAZ-REL-001', 'Unexpected Material / Process Release', 'Process Safety / Release', 'critical', 'Uncontrolled release of process fluids, gases, steam, dust, or other materials from equipment, piping, tanks, or nearby systems.', '["Incomplete isolation","Leaking valves","Incorrect line identification","Residual material","Damage to adjacent equipment."]'::jsonb, '["Burns","poisoning","fire","explosion","environmental damage","fatalities"]'::jsonb, '["Identify and isolate relevant sources","Verify isolation effectiveness","Drain, purge, or flush as appropriate","Assess adjacent systems","Establish release response and evacuation arrangements","Stop work if isolation integrity is in doubt"]'::jsonb, ARRAY['HOT','COLD','CSP','ELEC','EXC']::varchar[]),
  ('HAZ-PHYS-001', 'Noise and Vibration', 'Physical / Occupational Health', 'medium', 'Exposure to high noise levels or mechanical vibration from tools, machinery, and surrounding operations.', '["Excessive exposure duration","High-impact noise","Vibrating hand tools","Impaired communication."]'::jsonb, '["Hearing loss","hand-arm vibration disorders","fatigue","missed warnings"]'::jsonb, '["Assess noise and vibration exposure","Use quieter methods where practicable","Maintain tools","Limit exposure duration","Provide suitable hearing protection","Establish communication methods"]'::jsonb, ARRAY['HOT','COLD','WAH','ELEC','EXC']::varchar[]),
  ('HAZ-PHYS-002', 'Slips, Trips and Same-Level Falls', 'Physical / Access', 'medium', 'Unsafe walking or working surfaces caused by obstructions, spills, uneven ground, cables, or poor housekeeping.', '["Slipping on wet surfaces","Tripping over tools or cables","Falling on uneven terrain."]'::jsonb, '["Sprains","fractures","cuts","head injuries"]'::jsonb, '["Maintain housekeeping","Remove obstructions","Manage cables and hoses","Control spills","Provide suitable lighting and footwear","Maintain safe access routes"]'::jsonb, ARRAY['HOT','COLD','CSP','WAH','ELEC','EXC']::varchar[]),
  ('HAZ-ENV-002', 'Adverse Weather / Environmental Conditions', 'Environmental', 'high', 'Weather or environmental conditions that make work unsafe.', '["High winds affecting elevated work or suspended loads","Lightning near exposed work","Heavy rain affecting excavations","Poor visibility","Extreme temperatures."]'::jsonb, '["Falls","structural instability","electrocution","dropped loads","heat illness","flooding"]'::jsonb, '["Define task-specific weather limits","Monitor forecasts and actual conditions","Suspend work when limits are exceeded","Secure materials and equipment","Inspect affected work areas before restarting"]'::jsonb, ARRAY['HOT','COLD','WAH','ELEC','EXC']::varchar[]),
  ('HAZ-ENV-003', 'Inadequate Lighting / Visibility', 'Environmental / Access', 'medium', 'Insufficient lighting or visibility for safe access, inspection, tool use, or hazard identification.', '["Missed hazards","Incorrect connections","Unsafe movement","Impaired communication."]'::jsonb, '["Falls","contact injuries","equipment damage","incorrect safety-critical actions"]'::jsonb, '["Provide adequate task lighting","Maintain emergency lighting where required","Ensure lights are suitable for the hazardous area","Keep access routes illuminated","Provide backup lighting where loss of lighting would create danger"]'::jsonb, ARRAY['HOT','COLD','CSP','WAH','ELEC','EXC']::varchar[]),
  ('HAZ-ERG-001', 'Manual Handling / Ergonomic Strain', 'Ergonomic / Physical', 'medium', 'Physical strain from lifting, carrying, pushing, pulling, repetitive movements, or awkward working postures.', '["Heavy loads","Twisting","Overhead work","Repetitive tool use","Restricted access."]'::jsonb, '["Back injuries","muscle strains","joint injuries","musculoskeletal disorders"]'::jsonb, '["Assess load weight, shape, and handling conditions","Use mechanical aids or team lifting where appropriate","Plan material movement and access","Reduce repetitive and awkward movements","Provide suitable training and rest arrangements"]'::jsonb, ARRAY['HOT','COLD','CSP','WAH','ELEC','EXC']::varchar[]),
  ('HAZ-SIMOPS-001', 'Simultaneous Operations (SIMOPS) / Work Interface', 'Work Coordination', 'high', 'Interactions between concurrent jobs, equipment, personnel, or work areas that introduce additional hazards.', '["Hot work near flammable releases","Overhead work above other workers","Excavation near vehicle routes","Conflicting isolations","Incompatible simultaneous activities."]'::jsonb, '["Fire","explosion","dropped-object injuries","equipment damage","multiple fatalities"]'::jsonb, '["Identify overlapping permits and nearby activities","Conduct a SIMOPS assessment where required","Coordinate work through the designated site authority","Establish exclusion zones and work sequencing","Suspend or prohibit incompatible work when risks cannot be adequately controlled"]'::jsonb, ARRAY['HOT','COLD','CSP','WAH','ELEC','EXC']::varchar[]),
  ('HAZ-HUMAN-001', 'Communication Failure / Inadequate Supervision', 'Human Factors / Work Coordination', 'high', 'Failure to communicate work status, hazards, changes, isolation status, or emergency instructions to affected personnel.', '["Misunderstood instructions","Unauthorized restart","Missed warnings","Inadequate handover","Loss of contact with confined-space workers."]'::jsonb, '["Unsafe actions","delayed evacuation","exposure to hazards","serious injuries","fatalities"]'::jsonb, '["Conduct a pre-job briefing or toolbox talk","Confirm roles, responsibilities, and communication methods","Maintain contact arrangements for confined-space work","Record permit handovers and communicate status changes","Stop work if essential communication or supervision is lost"]'::jsonb, ARRAY['HOT','COLD','CSP','WAH','ELEC','EXC']::varchar[]),
  ('HAZ-EMER-001', 'Inadequate Emergency Response / Rescue Arrangements', 'Emergency Preparedness', 'critical', 'Inadequate preparation, equipment, personnel, or access to respond effectively to a foreseeable work-related emergency.', '["Delayed rescue","Unavailable emergency equipment","Untrained responders","Inaccessible casualty locations","Unsafe rescue attempts."]'::jsonb, '["Escalation of injuries","secondary casualties","permanent disability","fatalities"]'::jsonb, '["Define task-specific emergency and rescue arrangements","Confirm trained responders and suitable equipment are available","Maintain emergency access and reliable communication","Verify rescue arrangements before high-risk work begins","Ensure rescuers do not expose themselves to uncontrolled hazards"]'::jsonb, ARRAY['HOT','COLD','CSP','WAH','ELEC','EXC']::varchar[]);
--> statement-breakpoint
